    def test_ip_connectivity_for_all_configured_hosts(self, dscp, payload_size, source_address, trigger_all_configured_hosts=True, timeout=120):
        """
        Test IP connectivity for all configured hosts.

        :param int dscp: DSCP value. <0 to 63>
        :param int payload_size: Size of the payload. <16 to 61411>
        :param str source_address: Address of the source.
        :param bool trigger_all_configured_hosts: Trigger for all configured hosts. Defaults to True.
        :param int timeout: Time to wait for positive procedure result.
        :return: str: String with hosts IP addresses, test results, replies info, packets info, roundtrip times info.
        :raises: AdminApiProcedureFailureException if requestMessage contains `fail`.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-testIpConnectivity.html
        """
        parameters = {
            "triggerAllConfiguredHosts": trigger_all_configured_hosts,
            "dscp": dscp,
            "payloadSize": payload_size,
            "sourceAddress": source_address
        }
        self._api_client.execute_procedure(name="testIpConnectivity", parameters=parameters, timeout=timeout)

