    def set_ru_rad_debug_parameters(self, target_ru, domains, timeout=120, detailed_output=False):
        """
        Set Radio Unit RAD debug parameters.

        .. note::
            SUPPORTS CUSTOMER API ONLY

        :param str target_ru: (Mandatory) distName of a radio module. (i.e. "MRBTS-1/EQM-1/APEQM-1/RMOD-1")
        :param list domains: (Mandatory) List of domains. Minimum 1 item.
                             Schema: [{"domainName": string, // (mandatory, string)
                                       "parameters": [{ // (mandatory, list <minimum 1 item>)
                                            "name": string, // (mandatory, string)
                                            "value": string, // (mandatory, string)
                                            "persistency": enum // (optional, 'OneReset' | 'NotPersistent' - default value is 'NotPersistent')
                                        }]
                                     }]
        :param int timeout: Timeout for the operation, default set to 120 seconds.
        :param bool detailed_output: Return full request response when True, default set to False.
        :return Union[str,dict]: Result operation result as string ie. Completed, Failed, sometimes empty or full response dict.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-setRuRadDebugParameters.html
        """
        if not isinstance(domains, list):
            msg = "Parameter domains must be passed as a list."
            raise ValueError(msg)

        parameters = {'targetRU': target_ru,
                      'domains': domains}
        response = self._api_client.execute_customer_procedure(name="setRuRadDebugParameters",
                                                               parameters=parameters,
                                                               timeout=timeout)
        return response if detailed_output else response.get(self._provided_content.request_message)

